  if other!=a and other not in exceptions:check(dist(a,other)>=r+.25,f'arbor clearance {n} {other}')
for x,y in combinations(records,2):
 n,a,r,s,ls=x;m,b,q,t,ks=y
 if s!=t:continue
 if a==b:check(not ls&ks,f'same arbor layers {n} {m}')
 elif ls&ks and (n,m) not in meshes and (m,n) not in meshes:check(dist(a,b)>=r+q+.1,f'gear collision {n} {m}')
